#include "mesh.h"#include "FileStuff.h"#include "BMP.h"OSErr getWaterMask ( FSSpec theMeshFSSpec );OSErr getWaterMask ( FSSpec theMeshFSSpec ){//----------------------------------vars--------------------------------------------------	short		theMeshFileRef;	OSErr		theError;	int i, j, k;	long x, y;		char *theMask;	unsigned short *theMaskData;	long theWidth, theHeight, theSize;	meshHeader theMeshHeader;	Myth256Palette thePalette;//----------------------------------------------------------------------------------------			theError = FSpOpenDF ( &theMeshFSSpec, fsCurPerm, &theMeshFileRef );	if ( theError != noErr )		return theError;	FileRead ( &theMeshHeader, sizeof(struct meshHeader), theMeshFileRef );	theWidth = theMeshHeader.meshWidth * 256;	theHeight = theMeshHeader.meshHeight * 256;	theSize = theWidth * theHeight;	theMeshHeader.waterMaskOffset += 1088;	// make the palette	for (i = 0; i < 256; i++){		thePalette.color[i].blue = i;		thePalette.color[i].green = i;		thePalette.color[i].red = i;	}		theMask = (char *) NewPtr ( theSize );	if ( theMask == nil ){		FSClose ( theMeshFileRef );		return -1;	}	theMaskData = (unsigned short *) NewPtr ( theMeshHeader.waterMaskLength );	if ( theMaskData == nil ){		DisposePtr ( (Ptr) theMask );		FSClose ( theMeshFileRef );		return -1;	}	theError = SetFPos ( theMeshFileRef, fsFromStart, theMeshHeader.waterMaskOffset);	if ( theError == eofErr ){		DisposePtr ( (Ptr) theMaskData );		DisposePtr ( (Ptr) theMask );		FSClose ( theMeshFileRef );		return theError;	}		FileRead ( theMaskData, theMeshHeader.waterMaskLength, theMeshFileRef );	for ( j = 0; j < theSize; j++ )		theMask[j] = 0;		k = 0;	for ( y = 0; y < theHeight - 1 && (k * 2L) < theMeshHeader.waterMaskLength; ){		if ( theMaskData[k] == theWidth ){			y++;			k++;		}		else {			for ( x = theMaskData[k]; x <= theMaskData[k + 1]; x++ )				theMask[ ((theWidth - 1) - x) +  y * theWidth ] = 255;			k += 2;		}	}	theError = writeBMP( "\p:Graphics.out:watermask.bmp", theWidth, theHeight, &thePalette, theMask );	DisposePtr ( (Ptr) theMaskData );	DisposePtr ( theMask );	FSClose ( theMeshFileRef );		return theError;}